package compiler

import (
	"bytes"
	"fmt"
	"strings"
	"text/template"
)

const githubActionsTemplate = `name: "{{ .Name }}"
# Auto-generated by runforge CI Pipeline Exporter
# Estimated Token Savings: {{ printf "%.1f" .Metadata.EstimatedSavingsPct }}%

on:
  workflow_dispatch:
{{- if .Inputs }}
    inputs:
{{- range $key, $val := .Inputs }}
      {{ $key }}:
        description: "{{ $val.Description }}"
        required: false
        default: "{{ $val.Default }}"
{{- end }}
{{- end }}
  pull_request:
    branches: [ main, master ]

jobs:
  runforge-deterministic-execution:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

{{ range .Steps }}
      - name: "{{ .Name }}"
{{- if .Run }}
        run: |
          {{ .Run }}
{{- end }}
{{- if .Path }}
        run: |
          mkdir -p $(dirname "{{ .Path }}")
          cat << 'EOF' > "{{ .Path }}"
{{ .Content }}
EOF
{{- end }}
{{ end }}
`

const gitlabCITemplate = `# Auto-generated by runforge CI Pipeline Exporter
# Estimated Token Savings: {{ printf "%.1f" .Metadata.EstimatedSavingsPct }}%

stages:
  - execute

runforge_pipeline:
  stage: execute
  image: ubuntu:24.04
  before_script:
    - apt-get update && apt-get install -y git curl
  script:
{{ range .Steps }}
{{- if .Run }}
    - echo "--> Executing {{ .Name }}"
    - {{ .Run }}
{{- end }}
{{ end }}
`

const dockerfileTemplate = `# Auto-generated by runforge CI Pipeline Exporter
# Workflow: {{ .Name }}
FROM ubuntu:24.04

RUN apt-get update && apt-get install -y git curl ca-certificates && rm -rf /var/lib/apt/lists/*

WORKDIR /workspace

{{ range .Steps }}
{{- if .Run }}
RUN {{ .Run }}
{{- end }}
{{ end }}

CMD ["echo", "runforge compiled container execution finished successfully"]
`

// ExportGitHubActions translates a compiled playbook into a GitHub Actions YAML workflow.
func ExportGitHubActions(pb *Playbook) (string, error) {
	tmpl, err := template.New("gha").Parse(githubActionsTemplate)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, pb); err != nil {
		return "", err
	}
	return buf.String(), nil
}

// ExportGitLabCI translates a compiled playbook into a GitLab CI YAML configuration.
func ExportGitLabCI(pb *Playbook) (string, error) {
	tmpl, err := template.New("gitlab").Parse(gitlabCITemplate)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, pb); err != nil {
		return "", err
	}
	return buf.String(), nil
}

// ExportDockerfile translates a compiled playbook into an isolated container build recipe.
func ExportDockerfile(pb *Playbook) (string, error) {
	tmpl, err := template.New("docker").Parse(dockerfileTemplate)
	if err != nil {
		return "", err
	}
	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, pb); err != nil {
		return "", err
	}
	return buf.String(), nil
}

// ExportCI translates a playbook into the specified CI format ("github-actions", "gitlab", "docker").
func ExportCI(pb *Playbook, format string) (string, error) {
	switch strings.ToLower(format) {
	case "github-actions", "github", "gha":
		return ExportGitHubActions(pb)
	case "gitlab", "gitlab-ci":
		return ExportGitLabCI(pb)
	case "docker", "dockerfile", "container":
		return ExportDockerfile(pb)
	default:
		return "", fmt.Errorf("unsupported CI target format %q (options: github-actions, gitlab, docker)", format)
	}
}
